{"tool": "write_file", "args": {"path": "batches.py", "content": "from typing import List
from pydantic import BaseModel, conlist, PositiveInt, conint


# Define a custom constraint for min_items and max_items
PositiveIntList = List[conint(gt=0)]


class Batch(BaseModel):
    items: PositiveIntList

    @classmethod
    def __get_validators__(cls):
        yield cls.validate_to_instance
        yield cls.validate_length

    @classmethod
    def validate_to_instance(cls, v):
        return cls(items=v)

    @classmethod
    def validate_length(cls, v):
        if len(v) < 1 or len(v) > 3:
            raise ValueError('List must have between 1 and 3 items')
        return v


class TagSet(BaseModel):
    tags: PositiveIntList

    @classmethod
    def __get_validators__(cls):
        yield cls.validate_to_instance
        yield cls.validate_length

    @classmethod
    def validate_to_instance(cls, v):
        return cls(tags=v)

    @classmethod
    def validate_length(cls, v):
        if len(v) < 1:
            raise ValueError('List must have at least 1 item')
        return v


def make_batch(items):
    return Batch(items=items)

def make_tags(tags):
    return TagSet(tags=tags)
"}}

